using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");
Console.WriteLine($"  Properties: {personInfo.Properties.Count}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
//    With DefaultJsonTypeInfoResolver everything resolves, so use a
//    custom resolver that only knows about Person to show both paths.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    var typed = (JsonTypeInfo<Person>)found;
    Console.WriteLine($"\n✓ Metadata available for Person (properties: {typed.Properties.Count})");
}

if (limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? notFound))
{
    Console.WriteLine($"  Metadata available for Order (unexpected)");
}
else
{
    Console.WriteLine($"✗ No metadata for Order — resolver returned null, no exception thrown");
}

